from errors import CyclicDependencyError
from graph import DependencyGraph

class ExecutionPlanner:
    def plan(self, graph: DependencyGraph) -> list[str]:
        # Sort ready nodes lexicographically (ascending)
        ready = sorted([n for n in graph.all_nodes if graph.in_degree[n] == 0])
        in_degrees = dict(graph.in_degree)
        order = []
        while ready:
            node = ready.pop(0)
            order.append(node)
            # Process neighbors in lexicographical order
            for neighbor in sorted(graph.adj[node]):
                in_degrees[neighbor] -= 1
                if in_degrees[neighbor] == 0:
                    ready.append(neighbor)
        # If not all nodes were processed, a cycle exists
        if len(order) != len(graph.all_nodes):
            raise CyclicDependencyError("Cyclic dependency detected")
        return order

