from account import Beneficiary
from rounding import standard_round

class LedgerDistributor:
    def distribute(self, total_cents: int, beneficiaries: list[Beneficiary]) -> dict[str, int]:
        if not beneficiaries or total_cents <= 0:
            return {b.name: 0 for b in beneficiaries}
        total_weight = sum(b.weight for b in beneficiaries)
        if total_weight == 0:
            return {b.name: 0 for b in beneficiaries}

        # First pass: compute floor allocation and remainders
        base_shares = {}
        remainders = []
        allocated = 0
        for b in beneficiaries:
            # Integer division gives floor of (total_cents * weight) / total_weight
            exact = total_cents * b.weight
            floor_share = exact // total_weight
            remainder = exact % total_weight
            base_shares[b.name] = floor_share
            remainders.append((remainder, b.name))
            allocated += floor_share

        # Distribute any remaining cents (due to integer division truncation)
        remaining_cents = total_cents - allocated
        # Sort remainders descending to give extra cent to those with largest remainder
        remainders.sort(key=lambda x: x[0], reverse=True)

        # Allocate one extra cent to the first `remaining_cents` beneficiaries
        for i in range(remaining_cents):
            rem, name = remainders[i]
            base_shares[name] += 1

        return base_shares

