        if width <= 0:
            return []
        words = extract_words(text)
        lines = []
        current_line = []
        current_len = 0
        for w in words:
            # Calculate the length if we add this word
            if current_line:
                new_len = current_len + 1 + len(w)  # space before word
            else:
                new_len = len(w)
            # If adding the word would exceed the width, finalize current line
            if new_len > width:
                lines.append(" ".join(current_line))
                current_line = [w]
                current_len = len(w)
            else:
                current_line.append(w)
                current_len = new_len
        if current_line:
            lines.append(" ".join(current_line))
        return lines

