from collections import defaultdict
from models import Edge
from priority_queue import MinHeap

class DijkstraPathFinder:
    def find_shortest_path(self, edges: list[Edge], source: str, target: str) -> tuple[int, list[str]]:
        graph = defaultdict(list)
        for e in edges:
            graph[e.u].append((e.v, e.weight))

        heap = MinHeap()
        heap.push((0, [source]))
        visited = set()

        while len(heap) > 0:
            cost, path = heap.pop()
            curr = path[-1]
            if curr == target:
                return cost, path
            if curr in visited:
                continue
            visited.add(curr)
            # Iterate neighbors in a deterministic order to avoid nondeterministic routing
            for neighbor, weight in sorted(graph[curr], key=lambda x: x[0]):
                if neighbor not in visited:
                    heap.push((cost + weight, path + [neighbor]))
        return -1, []

